-- Revision-only maintenance must not compile the full diary update trigger.
-- Restrict both trigger programs to the fields they actually observe.
DROP TRIGGER block_revision;
CREATE TRIGGER block_revision AFTER UPDATE OF
  id, entry_id, user_id, content, created_at, occurred_at, images, category,
  is_done, done_at, url_metadata, tag, starts_at, ends_at, is_all_day, priority,
  extracted_text, due_at, due_all_day, source, time_confirmed_at, event_timing,
  timeline_placement, content_confirmed_at
ON blocks WHEN NEW.revision=OLD.revision
BEGIN
 UPDATE blocks SET revision=OLD.revision+1 WHERE id=NEW.id AND user_id=NEW.user_id;
END;

DROP TRIGGER diary_block_update;
CREATE TRIGGER diary_block_update AFTER UPDATE OF content, images, occurred_at, category, is_done, done_at, due_at, due_all_day ON blocks WHEN OLD.content IS NOT NEW.content OR OLD.images IS NOT NEW.images OR OLD.occurred_at IS NOT NEW.occurred_at OR OLD.category IS NOT NEW.category OR OLD.is_done IS NOT NEW.is_done OR OLD.done_at IS NOT NEW.done_at OR OLD.due_at IS NOT NEW.due_at OR OLD.due_all_day IS NOT NEW.due_all_day BEGIN
 INSERT INTO diary_generation_new_dates(user_id,date) SELECT NEW.user_id,date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))) FROM diary_generation_control WHERE singleton=1 AND enabled=1 AND new_records_only=1 AND NEW.category='event' AND EXISTS(SELECT 1 FROM diary_generation_new_blocks n WHERE n.user_id=NEW.user_id AND n.block_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM diary_generation_protected_dates p WHERE p.user_id=NEW.user_id AND p.date=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) ON CONFLICT DO NOTHING;
 INSERT INTO diary_generation_jobs(user_id,date,due_at,first_pending_at)
 SELECT OLD.user_id,date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0))),unixepoch()+5,unixepoch() FROM diary_generation_control WHERE singleton=1 AND OLD.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM diary_generation_scope s WHERE s.user_id=OLD.user_id AND s.date=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) AND (new_records_only=0 OR EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) OR EXISTS(SELECT 1 FROM diary_generation_new_blocks n WHERE n.user_id=OLD.user_id AND n.block_id=OLD.id)) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=OLD.user_id AND feature_key='diary_format'),1)=1
 ON CONFLICT(user_id,date) DO UPDATE SET generation=generation+1,status='queued',lease_token=NULL,lease_until=NULL,first_pending_at=COALESCE(first_pending_at,unixepoch()),due_at=min(unixepoch()+5,COALESCE(first_pending_at,unixepoch())+30),attempts=0,error_code=NULL;
 INSERT INTO diary_generation_outbox(user_id,date,generation,due_at) SELECT user_id,date,generation,due_at FROM diary_generation_jobs WHERE user_id=OLD.user_id AND date=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0))) AND EXISTS(SELECT 1 FROM diary_generation_control WHERE singleton=1 AND OLD.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM diary_generation_scope s WHERE s.user_id=OLD.user_id AND s.date=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) AND (new_records_only=0 OR EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))) OR EXISTS(SELECT 1 FROM diary_generation_new_blocks n WHERE n.user_id=OLD.user_id AND n.block_id=OLD.id)) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=OLD.user_id AND feature_key='diary_format'),1)=1) ON CONFLICT(user_id,date,generation) DO NOTHING;
 INSERT INTO diary_generation_jobs(user_id,date,due_at,first_pending_at)
 SELECT NEW.user_id,date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))),unixepoch()+5,unixepoch() FROM diary_generation_control WHERE singleton=1 AND NEW.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM diary_generation_scope s WHERE s.user_id=NEW.user_id AND s.date=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) AND (new_records_only=0 OR EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) OR EXISTS(SELECT 1 FROM diary_generation_new_blocks n WHERE n.user_id=NEW.user_id AND n.block_id=NEW.id)) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=NEW.user_id AND feature_key='diary_format'),1)=1 AND (OLD.category<>'event' OR date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))<>date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))))
 ON CONFLICT(user_id,date) DO UPDATE SET generation=generation+1,status='queued',lease_token=NULL,lease_until=NULL,first_pending_at=COALESCE(first_pending_at,unixepoch()),due_at=min(unixepoch()+5,COALESCE(first_pending_at,unixepoch())+30),attempts=0,error_code=NULL;
 INSERT INTO diary_generation_outbox(user_id,date,generation,due_at) SELECT user_id,date,generation,due_at FROM diary_generation_jobs WHERE user_id=NEW.user_id AND date=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))) AND EXISTS(SELECT 1 FROM diary_generation_control WHERE singleton=1 AND NEW.category='event' AND enabled=1 AND EXISTS(SELECT 1 FROM diary_generation_scope s WHERE s.user_id=NEW.user_id AND s.date=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) AND (new_records_only=0 OR EXISTS(SELECT 1 FROM json_each(allowed_dates) WHERE value=date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0)))) OR EXISTS(SELECT 1 FROM diary_generation_new_blocks n WHERE n.user_id=NEW.user_id AND n.block_id=NEW.id)) AND COALESCE((SELECT enabled FROM user_ai_feature_settings WHERE user_id=NEW.user_id AND feature_key='diary_format'),1)=1 AND (OLD.category<>'event' OR date(OLD.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=OLD.user_id),0)))<>date(NEW.occurred_at,printf('%+d hours',9-COALESCE((SELECT day_boundary_hour FROM user_ai_settings WHERE user_id=NEW.user_id),0))))) ON CONFLICT(user_id,date,generation) DO NOTHING;
  END;
